58		switch s := v.(type) {
59		case string:
60			return []byte(s)
61		case map[string]any:
62			enc, ok := s["base64"].(string)
63			if !ok {
64				t.Fatalf("non-string JSON value is not a {\"base64\":...} object: %v", s)
65			}
66			raw, err := base64.StdEncoding.DecodeString(enc)
67			if err != nil {
68				t.Fatalf("invalid base64 %q: %v", enc, err)
69			}
70			return raw
71		default:
72			t.Fatalf("JSON value is neither string nor base64 object: %T", v)
73			return nil
74		}
75	}
