77	// TestReviewJSONSuccessObject verifies the happy-path object: every text
78	// report field has its JSON counterpart, the target sequence is separate
79	// from policy versions, and stdout carries nothing but the object.
80	func TestReviewJSONSuccessObject(t *testing.T) {
81		const org = "acme payments"
82		path, cp := fixtureChain(t, org)
83	
84		_, obj, raw := parseJSONObject(t, jsonReviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint))
85	
86		if got := obj["target_sequence"]; got != float64(2) {
87			t.Fatalf("target_sequence = %v, want 2", got)
88		}
89		if got := obj["consistent"]; got != true {
90			t.Fatalf("consistent = %v, want true", got)
91		}
92		orig := jsonDecisionBlock(t, obj, "original")
93		recomp := jsonDecisionBlock(t, obj, "recomputed")
94		for name, block := range map[string]map[string]any{"original": orig, "recomputed": recomp} {
95			if block["allowed"] != true {
96				t.Fatalf("%s.allowed = %v, want true", name, block["allowed"])
97			}
98			if block["reason"] != "matched allow policy" {
99				t.Fatalf("%s.reason = %v", name, block["reason"])
100			}
101			matched, ok := block["matched_policies"].([]any)
102			if !ok || len(matched) != 1 || matched[0] != "p1 ledger" {
103				t.Fatalf("%s.matched_policies = %v", name, block["matched_policies"])
104			}
105			// Policy version is a peer field of the decision, distinct from the
106			// top-level target sequence.
107			if block["policy_version"] != float64(1) {
108				t.Fatalf("%s.policy_version = %v, want 1", name, block["policy_version"])
109			}
110		}
111		// Exactly the documented keys are present.
112		wantKeys := map[string]bool{
113			"target_sequence": true, "original": true,
114			"recomputed": true, "consistent": true,
115		}
116		for k := range obj {
117			if !wantKeys[k] {
118				t.Fatalf("unexpected top-level key %q", k)
119			}
120		}
121		if strings.Contains(raw, "target sequence") || strings.Contains(raw, "original decision") {
122			t.Fatalf("JSON output must not mix in the text report:\n%s", raw)
123		}
124	}
