203			Change: &darksafe.PolicyChange{
204				Version: 1,
205				Policies: []darksafe.Policy{
206					{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
207				},
208			},
209			PrevFingerprint: genesisFingerprintHex(org),
210		}
211		rec1.Fingerprint = envelopeFingerprint(syntheticEnvelope{
212			Org: rec1.Org, Seq: rec1.Seq, Kind: rec1.Kind,
213			Change: rec1.Change, PrevFingerprint: rec1.PrevFingerprint,
214		})
215		rec2 := darksafe.AuditRecord{
216			Org: org, Seq: 2, Kind: darksafe.AuditDecision,
217			Decision: &darksafe.DecisionRecord{
218				Request: req,
219				Decision: darksafe.Decision{
220					Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1,
221				},
222			},
223			PrevFingerprint: rec1.Fingerprint,
224		}
225		rec2.Fingerprint = envelopeFingerprint(syntheticEnvelope{
