305	// TestReviewJSONRendererRoundTripsEveryStringKind drives the renderer
306	// directly with reasons and policy identifiers spanning the full byte
307	// space, and recovers the exact original bytes through the documented
308	// representation.
309	func TestReviewJSONRendererRoundTripsEveryStringKind(t *testing.T) {
310		const (
311			loneFF   = "理\xff由"
312			loneFE   = " 策\xfe略 " // leading/trailing spaces around the invalid byte
313			genuine  = "因" + string(rune(0xFFFD)) + "子"
314			printed  = `说"明\分` + "\t\n\r" + "隔 中文"
315			newlines = "\n\n"
316		)
317		r := darksafe.OfflineDecisionReview{
318			Seq: 5,
319			Original: darksafe.Decision{
320				Allowed: false, Reason: loneFF,
321				Matched: []string{loneFF, loneFE, genuine, printed, newlines}, Version: 9,
322			},
323			Recomputed: darksafe.Decision{
324				Allowed: true, Reason: printed,
325				Matched: []string{"p\xff", "p\xfe", "p" + string(rune(0xFFFD))}, Version: 9,
326			},
327			Consistent: false,
328		}
329		payload, err := renderReviewJSON(r)
330		if err != nil {
331			t.Fatal(err)
332		}
333		// The raw stream is pure UTF-8 JSON: invalid bytes must never appear
334		// literally, so object boundaries cannot be corrupted by control or
335		// non-UTF-8 content.
336		if !json.Valid(payload) {
337			t.Fatalf("output is not valid JSON:\n%s", payload)
338		}
339		for _, bad := range []byte{0x00, 0xff, 0xfe} {
340			if bytes.IndexByte(payload, bad) >= 0 {
341				t.Fatalf("raw byte %#x leaked into JSON:\n%s", bad, payload)
342			}
343		}
344		// Mandatory escapes for the printable tricky string are present.
345		for _, frag := range []string{`\"`, `\\`, `\t`, `\n`, `\r`} {
346			if !bytes.Contains(payload, []byte(frag)) {
347				t.Fatalf("JSON missing escape %s:\n%s", frag, payload)
348			}
349		}
350		// Ordinary Chinese stays readable, not \u-escaped.
351		if !bytes.Contains(payload, []byte("中文")) {
352			t.Fatalf("ordinary Chinese should stay readable:\n%s", payload)
353		}
354	
355		var obj map[string]any
356		if err := json.Unmarshal(payload, &obj); err != nil {
357			t.Fatal(err)
358		}
359		orig := jsonDecisionBlock(t, obj, "original")
360		if got := recoverStringBytes(t, orig["reason"]); !bytes.Equal(got, []byte(loneFF)) {
361			t.Fatalf("reason round trip = %v, want %v", got, []byte(loneFF))
362		}
363		wantMatched := []string{loneFF, loneFE, genuine, printed, newlines}
364		gotList := orig["matched_policies"].([]any)
365		if len(gotList) != len(wantMatched) {
366			t.Fatalf("matched len = %d, want %d", len(gotList), len(wantMatched))
367		}
368		for i, want := range wantMatched {
369			if got := recoverStringBytes(t, gotList[i]); !bytes.Equal(got, []byte(want)) {
370				t.Fatalf("matched[%d] round trip = %v, want %v", i, got, []byte(want))
371			}
372		}
373	
374		// The critical distinguishability guarantee: 0xFF, 0xFE and a real
375		// U+FFFD take three different representations and decode back to three
376		// different byte strings.
377		recompMatched := jsonDecisionBlock(t, obj, "recomputed")["matched_policies"].([]any)
378		ff := recoverStringBytes(t, recompMatched[0])
379		fe := recoverStringBytes(t, recompMatched[1])
380		uffd := recoverStringBytes(t, recompMatched[2])
381		if !bytes.Equal(ff, []byte("p\xff")) || !bytes.Equal(fe, []byte("p\xfe")) ||
382			!bytes.Equal(uffd, []byte("p"+string(rune(0xFFFD)))) {
383			t.Fatalf("raw-byte recovery failed: ff=%v fe=%v uffd=%v", ff, fe, uffd)
384		}
385		if bytes.Equal(ff, fe) || bytes.Equal(ff, uffd) || bytes.Equal(fe, uffd) {
386			t.Fatal("0xFF, 0xFE and U+FFFD collapsed to the same bytes")
387		}
388		// On the wire the two invalid bytes are base64 objects, the genuine rune
389		// is a plain JSON string.
390		if _, isObj := recompMatched[0].(map[string]any); !isObj {
391			t.Fatalf("0xFF must be a base64 object, got %T", recompMatched[0])
392		}
393		if asStr, ok := recompMatched[2].(string); !ok || !strings.ContainsRune(asStr, '\uFFFD') {
394			t.Fatalf("genuine U+FFFD must stay a readable JSON string, got %T", recompMatched[2])
395		}
396	}
