536			}
537			if in.seq != 2 {
538				t.Fatalf("--json consumed --seq's value: seq=%d", in.seq)
539			}
540		})
541		t.Run("equals forms", func(t *testing.T) {
542			for _, tc := range []struct {
543				v    string
544				want bool
545				ok   bool
546			}{
547				{"true", true, true}, {"false", false, true},
