551				in, _, err := parseReviewArgs(args)
552				if tc.ok && (err != nil || in.json != tc.want) {
553					t.Fatalf("--json=%s: in.json=%v err=%v", tc.v, in.json, err)
554				}
555				if !tc.ok && err == nil {
556					t.Fatalf("--json=%s must be rejected", tc.v)
557				}
558			}
559		})
560		t.Run("json=false restores text report", func(t *testing.T) {
561			args := append(append([]string{}, base...), "--json=false")
562			code, out, errOut := runDispatch(t, args...)
563			if code != 0 || errOut != "" {
564				t.Fatalf("code=%d stderr=%q", code, errOut)
565			}
566			if !strings.Contains(out, "target sequence: 2") || strings.Contains(out, "\"target_sequence\"") {
567				t.Fatalf("--json=false must print the text report:\n%s", out)
568			}
569		})
570	}
571	
572	// TestReviewJSONIsReadOnly ensures JSON mode leaves the archive untouched.
573	func TestReviewJSONIsReadOnly(t *testing.T) {
574		const org = "acme"
575		path, cp := fixtureChain(t, org)
576		before, err := os.ReadFile(path)
577		if err != nil {
578			t.Fatal(err)
579		}
580		if code, _, errOut := runDispatch(t, jsonReviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...); code != 0 {
581			t.Fatalf("review: %s", errOut)
582		}
583		after, err := os.ReadFile(path)
584		if err != nil {
585			t.Fatal(err)
586		}
587		if !bytes.Equal(before, after) {
588			t.Fatal("--json modified the archive file")
589		}
590	}
591	
592	// TestReviewJSONHelpStillDocumentsFlag verifies the help entry point keeps
593	// documenting JSON and the existing required inputs.
594	func TestReviewJSONHelpStillDocumentsFlag(t *testing.T) {
595		code, out, errOut := runDispatch(t, "review", "--json", "--help")
596		if code != 0 || errOut != "" {
597			t.Fatalf("code=%d stderr=%q", code, errOut)
598		}
599		for _, want := range []string{"--json", "base64", "--archive", "Exit codes"} {
600			if !strings.Contains(out, want) {
601				t.Fatalf("help missing %q:\n%s", want, out)
602			}
603		}
604	}
605	
606	// buildLaterCorruptionArchive creates a chain where the target is the early
607	// decision at seq 2 but a later record (seq 4, subject "late-subject") is
608	// tampered with a recomputed frame checksum. Decoding succeeds; the whole
609	// chain validation must reject it.
610	func buildLaterCorruptionArchive(t *testing.T) (string, darksafe.Checkpoint) {
611		t.Helper()
612		const org = "acme"
613		s := darksafe.NewStore()
614		s.Publish(org, 0, []darksafe.Policy{
615			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
616		})
617		s.Decide(org, darksafe.OrgRequest{
618			SubjectOrg: org, ResourceOrg: org,
619			Subject:  darksafe.Subject{ID: "u1"},
620			Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
621			Action:   "read",
622		})
623		s.Publish(org, 1, nil)
624		s.Decide(org, darksafe.OrgRequest{
625			SubjectOrg: org, ResourceOrg: org,
626			Subject:  darksafe.Subject{ID: "late-subject"},
627			Resource: darksafe.Resource{ID: "r9", Scope: "org/a"},
628			Action:   "read",
629		})
630		recs, cp, err := s.AuditExport(org, 0)
631		if err != nil {
632			t.Fatal(err)
633		}
634		good, err := darksafe.EncodeAuditArchive(org, recs, cp)
635		if err != nil {
636			t.Fatal(err)
637		}
638		tampered := reframeArchive(t, good, func(payload []byte) {
639			idx := bytes.Index(payload, []byte("late-subject"))
640			if idx < 0 {
641				t.Fatal("later record subject not located")
642			}
643			payload[idx] ^= 0x01
644		})
645		path := filepath.Join(t.TempDir(), "late-damage-json.bin")
646		if err := os.WriteFile(path, tampered, 0o600); err != nil {
647			t.Fatal(err)
