		t.Fatalf("accepted prefix length = %d, want %d", len(got), limit)
	}
	if !bytes.Equal(got, full[:limit]) {
		t.Fatalf("accepted prefix altered:\n got %q\nwant %q", got, full[:limit])
	}
	if !strings.Contains(stderr.String(), "incomplete") {
